 foreach($f in @($PSCommandPath,"$RepoRoot/test/vi_sequencewait_native.cpp","$RepoRoot/test/vi_sequence_ack_proxy.cpp","$RepoRoot/src/vi_ready_json.h","$RepoRoot/src/vi_mh_rename.h","$RepoRoot/test/vi_sequence_rpc.cs","$RepoRoot/test/vi_r2_spies.h","$RepoRoot/test/vi_r2_pipe.cs","$RepoRoot/test/vi_r1_tail.cs","$RepoRoot/verify/vi_r1_identity.ps1","$RepoRoot/verify/vi_exited_cli_accounting.ps1","$RepoRoot/verify/vi_r1_lifecycle.ps1","$RepoRoot/verify/_vcvars.ps1",$NodeExe,(Join-Path $MinHookInclude 'MinHook.h'))){Pin $f}
 $modules=@(Get-ChildItem -LiteralPath $McpBuildDir -File -Filter '*.js');Require ($modules.Count-ge1-and$modules.Count-le96) 'bounded MCP module inventory';foreach($module in $modules){Pin $module.FullName}
 foreach($arch in @('x64','x86')){$entry=@{arch=$arch;completed=$false;error=$null};$arches.Add($entry);$proxyDirectory=$null;try{
